import { useId, type ComponentProps, type ElementType } from "react";

import { BrandList, type BrandEntry } from "@rhs-ui/commerce/brand-index/brand-list";
import { letterOf, monogram, normalise, type Brand } from "@rhs-ui/commerce/brand-index/groups";
import { AspectRatio } from "@rhs-ui/primitives/aspect-ratio";
import { cn } from "@/lib/utils";

export type { Brand } from "@rhs-ui/commerce/brand-index/groups";

export interface BrandIndexLabels {
  /** The heading. */
  title?: string;
  /** Under the heading when no description is passed. `{count}` brands. */
  summaryOne?: string;
  summaryOther?: string;
  /** The small heading above the tiles. */
  popular?: string;
  /** The name and the placeholder of the search field. */
  search?: string;
  /** The name of the A to Z bar. */
  jump?: string;
  /** What a screen reader hears as a group's heading. `{letter}`. */
  group?: string;
  /** The same for the group of names that start with a number or a symbol. */
  groupOther?: string;
  /** After a brand's number: `{count}` products. It is read out, not drawn. */
  countOne?: string;
  countOther?: string;
  /** Under the search while it filters. `{count}` brands match `{query}`. */
  matchOne?: string;
  matchOther?: string;
  /** In place of the list when nothing matches. `{query}`. */
  none?: string;
  /** Under it. */
  noneHint?: string;
  /** The button that empties the search and brings the whole list back. */
  clear?: string;
  /** In place of the list when there are no brands at all. */
  empty?: string;
}

const WORDS = {
  title: "Shop by brand",
  summaryOne: "{count} brand",
  summaryOther: "{count} brands, from A to Z",
  popular: "Popular brands",
  search: "Search brands",
  jump: "Jump to a letter",
  group: "Brands starting with {letter}",
  groupOther: "Brands starting with a number or a symbol",
  countOne: "{count} product",
  countOther: "{count} products",
  matchOne: "{count} brand matches “{query}”",
  matchOther: "{count} brands match “{query}”",
  none: "No brands match “{query}”",
  noneHint: "Check the spelling, or try fewer letters.",
  clear: "Show all brands",
  empty: "There are no brands to show yet.",
} satisfies Required<BrandIndexLabels>;

export interface BrandIndexProps extends Omit<ComponentProps<"section">, "children" | "title"> {
  /** Every brand the shop sells, in any order: they are sorted and grouped by their first letter. */
  brands: readonly Brand[];
  /** The names of the brands to feature as tiles above the list, in this order. A name that is not in `brands` is left out. */
  popular?: readonly string[];
  /** The heading. Defaults to "Shop by brand". */
  title?: string;
  /** The line under it. Without one, it says how many brands there are. */
  description?: string;
  /** Renders the links. Defaults to "a"; pass your router's Link. */
  linkAs?: ElementType;
  /** The heading's element: "h2" by default, "h3" inside a section that has its own h2. */
  headingAs?: "h2" | "h3";
  /** Always pass your application locale, so the names sort the same on the server and in the browser. */
  locale?: string;
  /** The words, for another language. */
  labels?: BrandIndexLabels;
}

const fill = (template: string, values: Record<string, string>): string => template.replace(/\{(\w+)\}/g, (_, key: string) => values[key] ?? "");

/**
 * A shop-by-brand page for shops with more brands than a menu can hold: the popular brands as tiles (a logo or
 * the brand's initials), then every brand under its first letter with its product count, and an A to Z bar that
 * jumps to each group, where a letter with no brand is shown but is not a link. A search field filters the list
 * as you type and says how many brands match, the groups are real headings so a screen reader can move from
 * letter to letter, and the columns balance on a wide screen and become one on a phone, where the bar scrolls
 * sideways. Without JavaScript the whole list is there.
 */
export function BrandIndex({ brands, popular = [], title, description, linkAs: Link = "a", headingAs: Heading = "h2", locale = "en-US", labels, className, ...props }: BrandIndexProps) {
  const words = { ...WORDS, ...labels };
  const id = useId();
  const numbers = new Intl.NumberFormat(locale);
  const plural = new Intl.PluralRules(locale);
  const collator = new Intl.Collator(locale, { sensitivity: "base", numeric: true });
  const countText = (value: number): string => fill(plural.select(value) === "one" ? words.countOne : words.countOther, { count: numbers.format(value) });

  const entries: BrandEntry[] = [...brands]
    .sort((a, b) => collator.compare(a.name, b.name))
    .map((brand) => ({
      key: `${brand.name}-${brand.href}`,
      name: brand.name,
      letter: letterOf(brand.name),
      search: normalise(brand.name),
      link: (
        <Link
          href={brand.href}
          className="-mx-2 flex items-baseline justify-between gap-4 rounded-md px-2 py-1.5 text-sm outline-none transition-colors duration-150 hover:bg-muted focus-visible:ring-[3px] focus-visible:ring-ring/40 motion-reduce:transition-none"
        >
          <span className="min-w-0 [overflow-wrap:anywhere]">{brand.name}</span>
          {brand.count !== undefined ? (
            <span className="shrink-0 text-xs text-muted-foreground tabular-nums">
              <span aria-hidden="true">{numbers.format(brand.count)}</span>
              <span className="sr-only">{countText(brand.count)}</span>
            </span>
          ) : null}
        </Link>
      ),
    }));

  const featured = popular.map((name) => brands.find((brand) => brand.name === name)).filter((brand): brand is Brand => brand !== undefined);

  const tiles = featured.length ? (
    <div>
      <h3 className="mb-3 text-xs font-medium tracking-[.18em] text-muted-foreground uppercase">{words.popular}</h3>
      <ul role="list" className="grid grid-cols-2 gap-3 @xl:grid-cols-3 @4xl:grid-cols-6">
        {featured.map((brand) => (
          <li key={`${brand.name}-${brand.href}`} className="min-w-0">
            <Link
              href={brand.href}
              className="group/tile flex h-full flex-col overflow-hidden rounded-xl border border-border bg-card outline-none transition-[border-color] duration-150 hover:border-foreground/30 focus-visible:ring-[3px] focus-visible:ring-ring/40 motion-reduce:transition-none"
            >
              <AspectRatio ratio={4 / 3} className="bg-muted/50">
                <span className="grid size-full place-items-center p-4">
                  {brand.logo ? (
                    // eslint-disable-next-line @next/next/no-img-element -- framework-neutral; a mark is a small vector or PNG
                    <img
                      src={brand.logo.src}
                      alt={brand.logo.alt}
                      loading="lazy"
                      decoding="async"
                      className="max-h-9 max-w-[78%] object-contain opacity-75 brightness-0 transition-opacity duration-150 group-hover/tile:opacity-100 motion-reduce:transition-none dark:invert"
                    />
                  ) : (
                    <span aria-hidden="true" className="text-3xl leading-none font-medium tracking-[-0.05em] text-foreground/75">
                      {monogram(brand.name)}
                    </span>
                  )}
                </span>
              </AspectRatio>
              <span className="flex items-baseline justify-between gap-3 border-t border-border px-3.5 py-2.5 text-sm">
                <span aria-hidden={brand.logo ? true : undefined} className="min-w-0 truncate font-medium">
                  {brand.name}
                </span>
                {brand.count !== undefined ? (
                  <span className="shrink-0 text-xs text-muted-foreground tabular-nums">
                    <span aria-hidden="true">{numbers.format(brand.count)}</span>
                    <span className="sr-only">{countText(brand.count)}</span>
                  </span>
                ) : null}
              </span>
            </Link>
          </li>
        ))}
      </ul>
    </div>
  ) : null;

  // With no brands at all there is nothing to count: "0 brands, from A to Z" would sit right above the line that says there are none.
  const summary = description ?? (entries.length > 0 ? fill(plural.select(entries.length) === "one" ? words.summaryOne : words.summaryOther, { count: numbers.format(entries.length) }) : null);

  const heading = (
    <header className="grid min-w-0 gap-1.5">
      <Heading id={`${id}-title`} className="text-2xl leading-tight font-medium tracking-[-0.035em] text-balance @3xl:text-3xl">
        {title ?? words.title}
      </Heading>
      {summary ? <p className="text-sm text-muted-foreground tabular-nums">{summary}</p> : null}
    </header>
  );

  return (
    <section data-slot="brand-index" aria-labelledby={`${id}-title`} className={cn("@container grid min-w-0 grid-cols-[minmax(0,1fr)] gap-8", className)} {...props}>
      <BrandList
        entries={entries}
        heading={heading}
        popular={tiles}
        locale={locale}
        words={{
          searchLabel: words.search,
          searchPlaceholder: words.search,
          jump: words.jump,
          group: words.group,
          groupOther: words.groupOther,
          matchOne: words.matchOne,
          matchOther: words.matchOther,
          none: words.none,
          noneHint: words.noneHint,
          clear: words.clear,
          empty: words.empty,
        }}
      />
    </section>
  );
}

"use client";

import { useEffect, useId, useRef, useState, type ReactNode } from "react";

import { IconSearch } from "@rhs-ui/icons";
import { LETTERS, OTHER, groupId, normalise } from "@rhs-ui/commerce/brand-index/groups";
import { Button } from "@rhs-ui/primitives/button";
import { SearchInput } from "@rhs-ui/primitives/search-input";

/** One brand, ready to draw: its link is already rendered, so the router's Link never has to cross into this module. */
export interface BrandEntry {
  /** Identity for the list. */
  key: string;
  name: string;
  /** The group it sits under: A to Z or "#". */
  letter: string;
  /** The name as it is searched: lower case, without accents. */
  search: string;
  /** The rendered link, with the name and the count in it. */
  link: ReactNode;
}

export interface BrandListWords {
  searchLabel: string;
  searchPlaceholder: string;
  jump: string;
  group: string;
  groupOther: string;
  matchOne: string;
  matchOther: string;
  none: string;
  noneHint: string;
  clear: string;
  empty: string;
}

export interface BrandListProps {
  entries: readonly BrandEntry[];
  /** The title block that sits beside the search field. */
  heading: ReactNode;
  /** The popular tiles. They are shown while the search is empty and give way to the results once someone types. */
  popular?: ReactNode;
  words: BrandListWords;
  locale: string;
}

const fill = (template: string, values: Record<string, string>): string => template.replace(/\{(\w+)\}/g, (_, key: string) => values[key] ?? "");

/** Says a sentence once typing settles, so a screen reader hears the result and not every keystroke. The first render says nothing. */
function useCalmStatus(text: string, delay = 450): string {
  const [said, setSaid] = useState("");
  const spoken = useRef(text);
  useEffect(() => {
    if (spoken.current === text) return;
    spoken.current = text;
    const timeout = window.setTimeout(() => setSaid(text), delay);
    return () => window.clearTimeout(timeout);
  }, [text, delay]);
  return said;
}

/**
 * The searchable part of a brand index: the search field, the popular tiles, the A to Z jump bar and every
 * brand under its letter. Typing filters the list as you go and a polite status says how many brands match;
 * letters with no brand left stop being links. The groups are real headings, so a screen reader can move from
 * letter to letter, and on a wide screen they flow into balanced columns.
 */
export function BrandList({ entries, heading, popular, words, locale }: BrandListProps) {
  const base = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const [query, setQuery] = useState("");
  const search = useRef<HTMLDivElement>(null);
  const bar = useRef<HTMLOListElement>(null);
  const needle = normalise(query.trim());
  const shown = needle ? entries.filter((entry) => entry.search.includes(needle)) : entries;
  const numbers = new Intl.NumberFormat(locale);
  const plural = new Intl.PluralRules(locale);

  const groups = new Map<string, BrandEntry[]>();
  for (const entry of shown) groups.set(entry.letter, [...(groups.get(entry.letter) ?? []), entry]);
  const letters = [...(entries.some((entry) => entry.letter === OTHER) ? [OTHER] : []), ...LETTERS];

  const result = needle ? fill(plural.select(shown.length) === "one" ? words.matchOne : words.matchOther, { count: numbers.format(shown.length), query: query.trim() }) : "";
  const said = useCalmStatus(needle ? (shown.length ? result : fill(words.none, { query: query.trim() })) : "");

  // The bar follows the matches: when the first letter that still has a brand is out of sight, it is scrolled to, so a phone is not left looking at a row of dim letters.
  useEffect(() => {
    const list = bar.current;
    const first = list?.querySelector<HTMLElement>("a")?.closest("li");
    if (list && first) list.scrollTo({ left: Math.max(0, first.offsetLeft - 8) });
  }, [needle, shown.length]);

  if (entries.length === 0) {
    return (
      <div data-slot="brand-list" className="contents">
        {heading}
        <p className="rounded-xl border border-dashed border-border px-6 py-14 text-center text-sm text-muted-foreground">{words.empty}</p>
      </div>
    );
  }

  return (
    <div data-slot="brand-list" className="contents">
      <div className="flex flex-wrap items-end justify-between gap-x-8 gap-y-5">
        {heading}
        <div ref={search} className="w-full @2xl:w-80">
          <SearchInput value={query} onValueChange={setQuery} placeholder={words.searchPlaceholder} aria-label={words.searchLabel} autoComplete="off" spellCheck={false} />
          <p aria-hidden="true" className="mt-2 h-4 text-xs text-muted-foreground tabular-nums">
            {shown.length ? result : ""}
          </p>
        </div>
      </div>

      {needle ? null : popular}

      <nav aria-label={words.jump} className="sticky top-[var(--sticky-top,0px)] z-10 min-w-0 border-y border-border bg-background">
        {/* The padding keeps the focus ring of the first and the last letter from being cut off by the scroller. On a narrow bar each cell is sized so that nine and a half of them fit, whatever the width, which leaves the next letter half in view: that is what says the bar scrolls. */}
        <ol ref={bar} role="list" className="relative flex overflow-x-auto px-1 py-1.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
          {letters.map((letter) => {
            const present = groups.has(letter);
            return (
              <li key={letter} className="min-w-8 flex-1 @max-md:min-w-[calc((100cqw_-_0.5rem)_/_9.5)]">
                {present ? (
                  <a
                    href={`#${groupId(base, letter)}`}
                    className="grid h-9 w-full place-items-center rounded-md text-sm font-medium text-foreground outline-none transition-colors hover:bg-muted focus-visible:ring-[3px] focus-visible:ring-ring/40 motion-reduce:transition-none"
                  >
                    {letter}
                  </a>
                ) : (
                  <span aria-hidden="true" className="grid h-9 w-full place-items-center text-sm font-medium text-muted-foreground/40">
                    {letter}
                  </span>
                )}
              </li>
            );
          })}
        </ol>
      </nav>

      {shown.length ? (
        <div className="columns-1 gap-x-12 @xl:columns-2 @4xl:columns-3">
          {letters
            .filter((letter) => groups.has(letter))
            .map((letter) => {
              const id = groupId(base, letter);
              return (
                <div key={letter} data-letter={letter} className="mb-8 break-inside-avoid">
                  <h3 id={id} className="scroll-mt-[calc(var(--sticky-top,0px)+3.75rem)] border-b border-border pb-2 text-2xl leading-none font-medium tracking-[-0.04em]">
                    <span className="sr-only">{letter === OTHER ? words.groupOther : fill(words.group, { letter })} </span>
                    <span aria-hidden="true">{letter}</span>
                  </h3>
                  <ul role="list" className="mt-2">
                    {(groups.get(letter) ?? []).map((entry) => (
                      <li key={entry.key}>{entry.link}</li>
                    ))}
                  </ul>
                </div>
              );
            })}
        </div>
      ) : (
        <div className="grid justify-items-center gap-3 rounded-xl border border-dashed border-border px-6 py-14 text-center">
          <span aria-hidden="true" className="grid size-11 place-items-center rounded-xl border border-border bg-muted">
            <IconSearch className="size-5" />
          </span>
          <p className="text-base font-medium text-balance">{fill(words.none, { query: query.trim() })}</p>
          <p className="max-w-sm text-sm text-muted-foreground">{words.noneHint}</p>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => {
              setQuery("");
              search.current?.querySelector("input")?.focus();
            }}
          >
            {words.clear}
          </Button>
        </div>
      )}

      <p role="status" className="sr-only">
        {said}
      </p>
    </div>
  );
}

/** One brand the shop sells. */
export interface Brand {
  /** What it is called: "Northwind". */
  name: string;
  /** The brand's page. */
  href: string;
  /** How many of its products the shop has. Shown beside the name. */
  count?: number;
  /** The mark, for the popular tiles. A transparent SVG or PNG: it is drawn in one colour, in the text colour. Without one the tile shows the brand's initials. */
  logo?: { src: string; alt: string };
}

/** The letters of the jump bar. */
export const LETTERS: readonly string[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");

/** The group for names that do not start with a letter: "1898 Mill". */
export const OTHER = "#";

/** Lower case with the accents taken off, so "Élan" is found by typing "elan" and sorts under E. */
export function normalise(text: string): string {
  return text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
}

/** The group a name belongs to: A to Z, or "#" for a number or a symbol. */
export function letterOf(name: string): string {
  const first = normalise(name.trim()).charAt(0).toUpperCase();
  return first.length === 1 && first >= "A" && first <= "Z" ? first : OTHER;
}

/** The first letters of the first two words, for a brand without a logo: "Cairn Outdoor" is "CO", "Northwind" is "N". */
export function monogram(name: string): string {
  const words = normalise(name)
    .split(/[^\p{L}\p{N}]+/u)
    .filter(Boolean);
  const letters = words.slice(0, 2).map((word) => word.charAt(0).toUpperCase());
  return letters.join("") || "?";
}

/** The id of a group's heading on the page, and the target of its jump link. */
export const groupId = (base: string, letter: string): string => `${base}-${letter === OTHER ? "other" : letter.toLowerCase()}`;
